/**
 * `process.env.NODE_ENV` gates the development-only warnings. Bundlers
 * replace it at build time (Next.js, Vite, webpack), so it works without
 * Node's types; declaring it here keeps type-checking and `no-undef`
 * linting passing in projects that don't have them.
 */
declare const process: { env: { NODE_ENV?: string } };

/** Title of a click-created event when no `createEvent` factory is given */
const DEFAULT_NEW_EVENT_TITLE = "New event";

/** How long the day opened by `showDay` stays highlighted, in milliseconds */
const HIGHLIGHT_DURATION_MS = 2000;

/** Days the week view shows when `numberOfDays` is not set */
const DEFAULT_NUMBER_OF_DAYS = 7;

/** Minute step drag, resize and click-to-create snap to when `snapMinutes` is not set */
const DEFAULT_SNAP_MINUTES = 15;

/** First hour the time grid shows when `dayStartHour` is not set (midnight) */
const DEFAULT_DAY_START_HOUR = 0;

/** Hour the time grid ends at when `dayEndHour` is not set (next midnight) */
const DEFAULT_DAY_END_HOUR = 24;

/** Clock style when `hourCycle` is not set */
const DEFAULT_HOUR_CYCLE: HourCycle = 12;

/** Calendars offered by the context menu when `calendars` is not set (stable identity) */
const NO_CALENDARS: CalendarInfo[] = [];

/** Config used outside a provider, and for every provider prop left unset */
const DEFAULT_CALENDAR_CONFIG: CalendarConfig = {
  snapMinutes: DEFAULT_SNAP_MINUTES,
  dayStartHour: DEFAULT_DAY_START_HOUR,
  dayEndHour: DEFAULT_DAY_END_HOUR,
  hourCycle: DEFAULT_HOUR_CYCLE,
  locale: enUS,
  calendars: NO_CALENDARS,
};

/** View settings used for every field `defaultViewSettings` leaves unset */
const DEFAULT_VIEW_SETTINGS: ViewSettings = {
  showWeekends: true,
  showDeclinedEvents: true,
  showWeekNumbers: false,
};

/** Initial events when uncontrolled without `defaultEvents` (stable identity) */
const NO_EVENTS: CalendarEvent[] = [];

/** What a mounted view draws, as reported through `reportView` */
interface ReportedView {
  /** The view's type */
  view: ViewType;
  /**
   * Day columns the view is fixed to, or `undefined` when it follows the
   * provider's `numberOfDays`
   */
  numberOfDays?: number;
}

/**
 * Provider state just before a view switch, restored when the mounted view
 * keeps its own type instead of following the switch
 */
interface ViewSwitchSnapshot {
  view: ViewType;
  numberOfDays: number;
  date: Date;
}

/** Inputs of `getAdoptedViewDate` */
interface AdoptedViewDateOptions {
  /** Date the provider shows now */
  currentDate: Date;
  /** View type being adopted */
  view: ViewType;
  /** Day count being adopted */
  numberOfDays: number;
  weekStartsOn: WeekStartsOn;
  /** State before the latest switch, if one is waiting for the view's report */
  pendingSwitch: ViewSwitchSnapshot | null;
  /** Whether the provider still shows its untouched starting date (today's period) */
  isOnStartingToday: boolean;
}

/**
 * Setters the views use to report what they currently show. Kept out of
 * `useCalendar()` because only the views write these values.
 */
interface CalendarViewSyncValue {
  /**
   * Any view: which view is mounted. Reported after every commit that
   * changes the view's props or the provider's state, so the provider can
   * adopt it (see CalendarProvider).
   */
  reportView: (reported: ReportedView) => void;
  /** Day/week view: the days on screen, updated live while scrolling */
  reportVisibleDays: (days: Date[]) => void;
  /** Month view: the month on screen, updated while scrolling */
  reportDisplayMonth: (month: Date) => void;
  /**
   * Closes an event's details popover: clears the selection only while
   * that event is still selected. A press on another event selects it
   * before the popover's outside-press dismissal runs, and that new
   * selection must survive it.
   */
  closeEventPopover: (eventId: string) => void;
}

/** Props for the internal EventContentSlot */
interface EventContentSlotProps extends EventContentProps {
  /**
   * Classes for the box around custom content: positions it above the event's
   * background layers and insets it like the default text
   */
  className: string;
  /** Default content, drawn as-is when no `renderEventContent` is set */
  fallback: React.ReactNode;
}

/** A message for the live region; `id` changes so a repeated text is read again */
interface Announcement {
  id: number;
  text: string;
}

/** Props of the stateful provider, once the starting date is known */
type CalendarStateProviderProps = CalendarProviderProps & {
  /** Starting date when `date` is not controlled */
  initialDate: Date;
};

const CalendarContext = React.createContext<CalendarContextValue | null>(null);

const CalendarViewSyncContext =
  React.createContext<CalendarViewSyncValue | null>(null);

/** No custom renderers: every slot uses its default (stable identity) */
const NO_RENDER_SLOTS: CalendarRenderSlots = {};

const CalendarRenderSlotsContext =
  React.createContext<CalendarRenderSlots>(NO_RENDER_SLOTS);

const CalendarConfigContext = React.createContext<CalendarConfig>(
  DEFAULT_CALENDAR_CONFIG,
);

/** Default `createEvent`: a "New event" covering the clicked slot */
function createDefaultEvent(range: NewEventRange): CalendarEvent {
  return {
    id: crypto.randomUUID(),
    title: DEFAULT_NEW_EVENT_TITLE,
    start: range.start,
    end: range.end,
  };
}

/**
 * Moves `date` by `amount` periods of the given view: days, months, the
 * agenda's `AGENDA_DAYS`, or the week view's step (`numberOfDays` below a
 * week, a week otherwise)
 */
function shiftPeriod(
  date: Date,
  view: ViewType,
  amount: number,
  numberOfDays: number,
): Date {
  if (view === "day") return addDays(date, amount);
  if (view === "month") return addMonths(date, amount);
  if (view === "agenda") return addDays(date, amount * AGENDA_DAYS);
  return addDays(date, amount * getWeekViewStepDays(numberOfDays));
}

/**
 * First day of the agenda when switching to it from `view`: today when the
 * period on screen contains it, since an agenda lists what's coming up, and
 * the period's first day otherwise
 */
function getAgendaStartFrom(
  date: Date,
  view: ViewType,
  numberOfDays: number,
  now: Date,
): Date {
  const periodEnd = shiftPeriod(date, view, 1, numberOfDays);
  if (now >= date && now < periodEnd) return startOfDay(now);
  return startOfDay(date);
}

/**
 * Date the provider moves to when it adopts a mounted view's type or day
 * count
 */
function getAdoptedViewDate({
  currentDate,
  view,
  numberOfDays,
  weekStartsOn,
  pendingSwitch,
  isOnStartingToday,
}: AdoptedViewDateOptions): Date {
  // The mounted view didn't follow the latest switch: undo it, date included
  if (
    pendingSwitch?.view === view &&
    pendingSwitch.numberOfDays === numberOfDays
  ) {
    return pendingSwitch.date;
  }
  // Still on the starting date picked before any view mounted: today's
  // period of the mounted view instead (today for a day view)
  if (isOnStartingToday) {
    return getPeriodStart(new Date(), view, weekStartsOn, numberOfDays);
  }
  // The app swapped in a view of another type: land like switchView
  if (view === "day") return startOfDay(new Date());
  return getPeriodStart(currentDate, view, weekStartsOn, numberOfDays);
}

/**
 * Keeps the visible hours a valid range of whole hours: the start within
 * 0-23, the end after it and at most 24
 */
function resolveDayHours(
  dayStartHour: number,
  dayEndHour: number,
): Pick<CalendarConfig, "dayStartHour" | "dayEndHour"> {
  const start = Math.min(Math.max(Math.floor(dayStartHour), 0), 23);
  const end = Math.min(Math.max(Math.ceil(dayEndHour), start + 1), 24);
  return { dayStartHour: start, dayEndHour: end };
}

/**
 * Owns calendar state (events, view, date, selection, view settings) and
 * navigation, and shares them with the views through `useCalendar()`.
 *
 * Without `date` or `defaultDate` the calendar starts on today's period.
 * Today is unknown during server rendering and hydration, so in that case
 * nothing is rendered until hydration finishes; server and client markup
 * always match.
 *
 * `TEvent` is the app's event type. It is usually inferred from `events` or
 * `defaultEvents`; read it back with `useCalendar<TEvent>()`.
 *
 * Navigation (`goToPrev`, `goToNext`, `goToToday`, the shortcuts), header
 * info (`monthName`, `weekNumber`) and `visibleDays` follow the provider's
 * `view` and `numberOfDays`. Render one view per provider: it reports what
 * it draws, and the provider lines up with it as follows.
 *
 * - Uncontrolled `view`: the provider adopts the mounted view's type
 *   (DayView, WeekView, MonthView, AgendaView, or TimeGrid's `view`), so a
 *   lone view just works. `defaultView` only applies until a view mounts.
 * - Controlled `view` always wins: the provider never changes it to match
 *   the mounted view (development builds warn about a mismatch). Render the
 *   view it names, e.g. `<TimeGrid view={view} />`.
 * - A view's `numberOfDays` prop (WeekView, TimeGrid) works the same way
 *   against the provider's `numberOfDays`. Without it the view follows the
 *   provider.
 * - Switches the mounted view doesn't follow (`switchView`, `showDay`,
 *   `setNumberOfDays`, the D/W/M and 2-9 shortcuts while a lone WeekView
 *   stays mounted) are undone, date included. To make switching work,
 *   render the view from `view`, as the demo does with `TimeGrid`.
 * - Without `date` or `defaultDate`, the calendar starts on today's period
 *   of the adopted view: today for DayView and AgendaView, this week for
 *   WeekView.
 */
export function CalendarProvider<TEvent extends CalendarEvent = CalendarEvent>(
  props: CalendarProviderProps<TEvent>,
) {
  // `null` on the server and during hydration
  const today = useToday();
  const todayPeriodStart = today
    ? getPeriodStart(
        today,
        props.view ?? props.defaultView ?? "week",
        props.weekStartsOn ?? 0,
        props.numberOfDays ??
          props.defaultNumberOfDays ??
          DEFAULT_NUMBER_OF_DAYS,
      )
    : null;
  const initialDate = props.defaultDate ?? todayPeriodStart ?? props.date;

  if (!initialDate) return null;

  // The state below works with base `CalendarEvent`s, because the context
  // holding it can't be generic. It only stores, moves and hands back the
  // app's own event objects, so every event it passes to these callbacks is
  // a `TEvent`; `useCalendar<TEvent>()` restores the type on the way out.
  const baseProps = props as CalendarProviderProps;

  return <CalendarStateProvider {...baseProps} initialDate={initialDate} />;
}

function CalendarStateProvider({
  initialDate,
  events: eventsProp,
  defaultEvents,
  onEventsChange,
  view: viewProp,
  defaultView = "week",
  onViewChange,
  date: dateProp,
  defaultDate,
  onDateChange,
  weekStartsOn = 0,
  numberOfDays: numberOfDaysProp,
  defaultNumberOfDays = DEFAULT_NUMBER_OF_DAYS,
  onNumberOfDaysChange,
  defaultViewSettings,
  snapMinutes = DEFAULT_SNAP_MINUTES,
  dayStartHour = DEFAULT_DAY_START_HOUR,
  dayEndHour = DEFAULT_DAY_END_HOUR,
  hourCycle = DEFAULT_HOUR_CYCLE,
  locale = enUS,
  calendars = NO_CALENDARS,
  createEvent,
  onEventCreate,
  onEventUpdate,
  onEventSelect,
  onVisibleRangeChange,
  loading = false,
  renderEventContent,
  renderEventDetails,
  children,
}: CalendarStateProviderProps) {
  const [events, setEvents] = useControllableState({
    prop: eventsProp,
    defaultProp: defaultEvents ?? NO_EVENTS,
    onChange: onEventsChange,
  });
  const [view, setView] = useControllableState({
    prop: viewProp,
    defaultProp: defaultView,
    onChange: onViewChange,
  });
  const [currentDate, setCurrentDate] = useControllableState({
    prop: dateProp,
    defaultProp: initialDate,
    onChange: onDateChange,
  });
  const [numberOfDays, setNumberOfDays] = useControllableState({
    prop: numberOfDaysProp,
    defaultProp: defaultNumberOfDays,
    onChange: onNumberOfDaysChange,
  });
  const [viewSettings, setViewSettings] = React.useState<ViewSettings>(() => ({
    ...DEFAULT_VIEW_SETTINGS,
    ...defaultViewSettings,
  }));
  const [selectedEventId, setSelectedEventId] = React.useState<string | null>(
    null,
  );
  const [highlightedDate, setHighlightedDate] = React.useState<Date | null>(
    null,
  );
  /** Month the month view shows; kept after leaving it until it reports again */
  const [displayMonth, setDisplayMonth] = React.useState<Date | null>(null);
  const [visibleDays, setVisibleDays] = React.useState<Date[]>(() =>
    getVisibleDays(currentDate, view, numberOfDays),
  );
  /** ID of a just-created event whose title input should be focused once */
  const [titleFocusEventId, setTitleFocusEventId] = React.useState<
    string | null
  >(null);
  /** Latest move, resize or create, read out by the live region */
  const [announcement, setAnnouncement] = React.useState<Announcement | null>(
    null,
  );
  /** Latest events, so `updateEvent` can compare without depending on them */
  const eventsRef = React.useRef(events);
  /**
   * State before the latest switch of view or day count, so a mounted view
   * that keeps its own type can undo it. Read and cleared by the next report.
   */
  const pendingSwitchRef = React.useRef<ViewSwitchSnapshot | null>(null);
  /** Whether the controlled-view mismatch warning was already logged */
  const hasWarnedViewConflictRef = React.useRef(false);
  /** The mounted view's latest report, or `null` while no view has reported */
  const mountedViewRef = React.useRef<ReportedView | null>(null);
  /** Latest `onVisibleRangeChange`, so a new callback alone doesn't report */
  const onVisibleRangeChangeRef = React.useRef(onVisibleRangeChange);
  /** Start and end times last passed to `onVisibleRangeChange` */
  const reportedRangeKeyRef = React.useRef<string | null>(null);
  /** Whether the starting date is today's period (no `date` or `defaultDate`) */
  const startsOnToday = dateProp === undefined && defaultDate === undefined;
  const initialTime = initialDate.getTime();

  React.useEffect(() => {
    eventsRef.current = events;
  }, [events]);

  React.useEffect(() => {
    onVisibleRangeChangeRef.current = onVisibleRangeChange;
  }, [onVisibleRangeChange]);

  // The highlight from `showDay` is a brief flash, not a lasting state
  React.useEffect(() => {
    if (!highlightedDate) return;
    const timer = setTimeout(
      () => setHighlightedDate(null),
      HIGHLIGHT_DURATION_MS,
    );
    return () => clearTimeout(timer);
  }, [highlightedDate]);

  // Month view shows no day range; consumers sync to `displayMonth` instead
  React.useEffect(() => {
    if (view !== "month") return;
    setVisibleDays([]);
  }, [view]);

  const selectedEvent = React.useMemo(
    () => events.find((e) => e.id === selectedEventId) ?? null,
    [events, selectedEventId],
  );

  // Only honor the focus request while that event is still the selected one
  const pendingTitleFocusId =
    titleFocusEventId === selectedEventId ? titleFocusEventId : null;

  const clearTitleFocus = React.useCallback(() => {
    setTitleFocusEventId(null);
  }, []);

  const selectEvent = React.useCallback(
    (eventId: string) => {
      setSelectedEventId(eventId);
      onEventSelect?.(eventId);
    },
    [onEventSelect],
  );

  const clearSelection = React.useCallback(() => {
    setSelectedEventId(null);
  }, []);

  const announce = React.useCallback((text: string) => {
    setAnnouncement((prev) => ({ id: (prev?.id ?? 0) + 1, text }));
  }, []);

  const updateEvent = React.useCallback(
    (updatedEvent: CalendarEvent) => {
      const previous = eventsRef.current.find((e) => e.id === updatedEvent.id);
      setEvents((prev) =>
        prev.map((e) => (e.id === updatedEvent.id ? updatedEvent : e)),
      );
      onEventUpdate?.(updatedEvent);

      // Moves and resizes (drag, keyboard, or the details) are announced;
      // edits that keep the time, like the title, are not
      if (!previous) return;
      const message = describeEventChange(
        previous,
        updatedEvent,
        hourCycle,
        locale,
      );
      if (message) announce(message);
    },
    [setEvents, onEventUpdate, hourCycle, locale, announce],
  );

  const addEventFromRange = React.useCallback(
    (range: NewEventRange) => {
      const newEvent = (createEvent ?? createDefaultEvent)(range);
      if (!newEvent) return;
      setEvents((prev) => [...prev, newEvent]);
      onEventCreate?.(newEvent);
      selectEvent(newEvent.id);
      setTitleFocusEventId(newEvent.id);
      announce(describeEventCreated(newEvent, hourCycle, locale));
    },
    [
      createEvent,
      setEvents,
      onEventCreate,
      selectEvent,
      hourCycle,
      locale,
      announce,
    ],
  );

  const goToToday = React.useCallback(() => {
    setCurrentDate(
      getPeriodStart(new Date(), view, weekStartsOn, numberOfDays),
    );
  }, [view, weekStartsOn, numberOfDays, setCurrentDate]);

  const goToPrev = React.useCallback(() => {
    setCurrentDate((prev) => shiftPeriod(prev, view, -1, numberOfDays));
  }, [view, numberOfDays, setCurrentDate]);

  const goToNext = React.useCallback(() => {
    setCurrentDate((prev) => shiftPeriod(prev, view, 1, numberOfDays));
  }, [view, numberOfDays, setCurrentDate]);

  const goToDate = React.useCallback(
    (date: Date) => setCurrentDate(date),
    [setCurrentDate],
  );

  const switchView = React.useCallback(
    (newView: ViewType) => {
      if (newView === view) return;
      pendingSwitchRef.current = { view, numberOfDays, date: currentDate };
      setView(newView);
      if (newView === "day") {
        setCurrentDate(startOfDay(new Date()));
        return;
      }
      if (newView === "agenda") {
        setCurrentDate((prev) =>
          getAgendaStartFrom(prev, view, numberOfDays, new Date()),
        );
        return;
      }
      setCurrentDate((prev) =>
        getPeriodStart(prev, newView, weekStartsOn, numberOfDays),
      );
    },
    [view, currentDate, weekStartsOn, numberOfDays, setView, setCurrentDate],
  );

  const changeNumberOfDays = React.useCallback(
    (count: number) => {
      if (count !== numberOfDays) {
        pendingSwitchRef.current = { view, numberOfDays, date: currentDate };
      }
      setNumberOfDays(count);
      if (view !== "week") return;
      // Going back to a full week starts on the week's first day again
      setCurrentDate((prev) => {
        const next = getPeriodStart(prev, "week", weekStartsOn, count);
        return next.getTime() === prev.getTime() ? prev : next;
      });
    },
    [
      view,
      numberOfDays,
      currentDate,
      weekStartsOn,
      setNumberOfDays,
      setCurrentDate,
    ],
  );

  const showDay = React.useCallback(
    (date: Date) => {
      if (view !== "week") {
        pendingSwitchRef.current = { view, numberOfDays, date: currentDate };
      }
      setView("week");
      setCurrentDate(getPeriodStart(date, "week", weekStartsOn, numberOfDays));
      setHighlightedDate(date);
    },
    [view, currentDate, weekStartsOn, numberOfDays, setView, setCurrentDate],
  );

  const reportView = React.useCallback(
    (reported: ReportedView) => {
      mountedViewRef.current = reported;
      const pendingSwitch = pendingSwitchRef.current;
      pendingSwitchRef.current = null;
      // Controlled values always win over the mounted view
      const nextView = viewProp ?? reported.view;
      const nextNumberOfDays =
        numberOfDaysProp ?? reported.numberOfDays ?? numberOfDays;
      const conflictsWithControlled =
        reported.view !== nextView ||
        (reported.numberOfDays !== undefined &&
          reported.numberOfDays !== nextNumberOfDays);
      if (
        conflictsWithControlled &&
        process.env.NODE_ENV !== "production" &&
        !hasWarnedViewConflictRef.current
      ) {
        hasWarnedViewConflictRef.current = true;
        console.warn(
          `CalendarProvider: the mounted ${reported.view} view doesn't match the controlled \`view\` / \`numberOfDays\` props, which navigation follows. Render the view they name, e.g. <TimeGrid view={view} />.`,
        );
      }
      if (nextView === view && nextNumberOfDays === numberOfDays) return;

      const nextDate = getAdoptedViewDate({
        currentDate,
        view: nextView,
        numberOfDays: nextNumberOfDays,
        weekStartsOn,
        pendingSwitch,
        isOnStartingToday:
          startsOnToday && currentDate.getTime() === initialTime,
      });
      setView(nextView);
      setNumberOfDays(nextNumberOfDays);
      setCurrentDate(nextDate);
      // Header info reads the visible days: match them to the new date before
      // the first paint (the view reports its own after it). A controlled date
      // may not change, so it waits for the view's report.
      if (dateProp !== undefined) return;
      setVisibleDays(
        nextView === "month"
          ? []
          : getVisibleDays(nextDate, nextView, nextNumberOfDays),
      );
    },
    [
      viewProp,
      numberOfDaysProp,
      dateProp,
      view,
      numberOfDays,
      currentDate,
      startsOnToday,
      initialTime,
      weekStartsOn,
      setView,
      setNumberOfDays,
      setCurrentDate,
    ],
  );

  const toggleWeekends = React.useCallback(() => {
    setViewSettings((prev) => ({ ...prev, showWeekends: !prev.showWeekends }));
  }, []);

  const toggleDeclinedEvents = React.useCallback(() => {
    setViewSettings((prev) => ({
      ...prev,
      showDeclinedEvents: !prev.showDeclinedEvents,
    }));
  }, []);

  const toggleWeekNumbers = React.useCallback(() => {
    setViewSettings((prev) => ({
      ...prev,
      showWeekNumbers: !prev.showWeekNumbers,
    }));
  }, []);

  // Week/day views name the month after the LAST visible day, so a week
  // crossing into the next month is labeled with the later month (Notion
  // Calendar's behavior). Month view labels its own month instead, and the
  // agenda the month it starts in.
  const headerDate =
    view === "month"
      ? (displayMonth ?? currentDate)
      : (visibleDays[0] ?? currentDate);
  const headerRangeEnd =
    view === "month" || view === "agenda"
      ? undefined
      : visibleDays[visibleDays.length - 1];
  const { monthName, year, weekNumber } = getCalendarHeaderInfo(
    headerDate,
    weekStartsOn,
    locale,
    headerRangeEnd,
  );

  // Derived from the provider's own period, not the live `visibleDays`, so a
  // horizontal scroll moves it once it snaps instead of at every day it passes
  const range = getVisibleRange(
    currentDate,
    view,
    numberOfDays,
    weekStartsOn,
    viewSettings.showWeekends,
  );
  const rangeStartTime = range.start.getTime();
  const rangeEndTime = range.end.getTime();
  const visibleRange = React.useMemo<VisibleRange>(
    () => ({ start: new Date(rangeStartTime), end: new Date(rangeEndTime) }),
    [rangeStartTime, rangeEndTime],
  );

  // Report each new range once. While the provider is still adopting the
  // mounted view (its first commit, or a switch the view is undoing), the
  // range belongs to a view that isn't on screen, so wait for the next one.
  // Same resolution as `reportView`: controlled values win.
  React.useEffect(() => {
    const mounted = mountedViewRef.current;
    if (mounted) {
      const adoptedView = viewProp ?? mounted.view;
      const adoptedNumberOfDays =
        numberOfDaysProp ?? mounted.numberOfDays ?? numberOfDays;
      if (adoptedView !== view || adoptedNumberOfDays !== numberOfDays) return;
    }
    const key = `${visibleRange.start.getTime()}-${visibleRange.end.getTime()}`;
    if (reportedRangeKeyRef.current === key) return;
    reportedRangeKeyRef.current = key;
    onVisibleRangeChangeRef.current?.(visibleRange);
  }, [visibleRange, view, numberOfDays, viewProp, numberOfDaysProp]);

  const value = React.useMemo<CalendarContextValue>(
    () => ({
      events,
      view,
      currentDate,
      weekStartsOn,
      numberOfDays,
      viewSettings,
      visibleDays,
      displayMonth,
      visibleRange,
      loading,
      selectedEventId,
      selectedEvent,
      highlightedDate,
      monthName,
      year,
      weekNumber,
      goToToday,
      goToPrev,
      goToNext,
      goToDate,
      switchView,
      setNumberOfDays: changeNumberOfDays,
      selectEvent,
      clearSelection,
      addEventFromRange,
      updateEvent,
      toggleWeekends,
      toggleDeclinedEvents,
      toggleWeekNumbers,
      showDay,
    }),
    [
      events,
      view,
      currentDate,
      weekStartsOn,
      numberOfDays,
      viewSettings,
      visibleDays,
      displayMonth,
      visibleRange,
      loading,
      selectedEventId,
      selectedEvent,
      highlightedDate,
      monthName,
      year,
      weekNumber,
      goToToday,
      goToPrev,
      goToNext,
      goToDate,
      switchView,
      changeNumberOfDays,
      selectEvent,
      clearSelection,
      addEventFromRange,
      updateEvent,
      toggleWeekends,
      toggleDeclinedEvents,
      toggleWeekNumbers,
      showDay,
    ],
  );

  const closeEventPopover = React.useCallback((eventId: string) => {
    setSelectedEventId((prev) => (prev === eventId ? null : prev));
  }, []);

  const viewSync = React.useMemo<CalendarViewSyncValue>(
    () => ({
      reportView,
      reportVisibleDays: setVisibleDays,
      reportDisplayMonth: setDisplayMonth,
      closeEventPopover,
    }),
    [reportView, closeEventPopover],
  );

  const renderSlots = React.useMemo<CalendarRenderSlots>(
    () => ({ renderEventContent, renderEventDetails }),
    [renderEventContent, renderEventDetails],
  );

  const config = React.useMemo<CalendarConfig>(
    () => ({
      snapMinutes: Math.max(1, Math.round(snapMinutes)),
      ...resolveDayHours(dayStartHour, dayEndHour),
      hourCycle,
      locale,
      calendars,
    }),
    [snapMinutes, dayStartHour, dayEndHour, hourCycle, locale, calendars],
  );

  return (
    <CalendarContext.Provider value={value}>
      <CalendarViewSyncContext.Provider value={viewSync}>
        <CalendarRenderSlotsContext.Provider value={renderSlots}>
          <CalendarConfigContext.Provider value={config}>
            <EventTitleFocusProvider
              pendingEventId={pendingTitleFocusId}
              clearPending={clearTitleFocus}
            >
              {children}
              {/* Announces moves, resizes and creates to screen readers */}
              <div role="status" aria-live="polite" className="sr-only">
                {announcement && (
                  <span key={announcement.id}>{announcement.text}</span>
                )}
              </div>
            </EventTitleFocusProvider>
          </CalendarConfigContext.Provider>
        </CalendarRenderSlotsContext.Provider>
      </CalendarViewSyncContext.Provider>
    </CalendarContext.Provider>
  );
}

/**
 * Returns calendar state and actions from the nearest CalendarProvider.
 * Pass the event type given to the provider to get events and callbacks
 * typed with it. Throws when used outside a provider.
 */
export function useCalendar<
  TEvent extends CalendarEvent = CalendarEvent,
>(): CalendarContextValue<TEvent> {
  const context = React.useContext(CalendarContext);
  if (!context) {
    throw new Error("useCalendar must be used within a CalendarProvider.");
  }
  // React context can't be generic, so the provider stores its value with
  // base `CalendarEvent` types. The events in it are the app's own objects,
  // so this restores the `TEvent` the caller gave the provider. `TEvent` is
  // both read (events) and written (updateEvent), so TypeScript sees the two
  // types as unrelated and the cast goes through `unknown`.
  return context as unknown as CalendarContextValue<TEvent>;
}

/**
 * Returns the display and interaction settings of the nearest
 * CalendarProvider (`snapMinutes`, `dayStartHour`, `dayEndHour`,
 * `hourCycle`, `locale`, `calendars`), e.g. to format times in a custom
 * `renderEventContent` the way the calendar does. Outside a provider it
 * returns the defaults.
 */
export function useCalendarConfig(): CalendarConfig {
  return React.useContext(CalendarConfigContext);
}

/**
 * Internal: the custom renderers set on the nearest CalendarProvider, for
 * the event items and popovers that draw them. Empty (all defaults) outside
 * a provider.
 */
export function useCalendarRenderSlots(): CalendarRenderSlots {
  return React.useContext(CalendarRenderSlotsContext);
}

/**
 * Internal: lets the views report what they show (visible days, displayed
 * month) back to the provider. Throws when used outside a CalendarProvider.
 */
export function useCalendarViewSync(): CalendarViewSyncValue {
  const context = React.useContext(CalendarViewSyncContext);
  if (!context) {
    throw new Error(
      "useCalendarViewSync must be used within a CalendarProvider.",
    );
  }
  return context;
}

/**
 * Internal: draws an event item's content area. Renders `renderEventContent`
 * inside a positioned box when the provider has one, otherwise the item's
 * default content unchanged. As its own component, hooks called by the
 * custom renderer stay isolated from the event item's.
 */
export function EventContentSlot({
  className,
  fallback,
  ...contentProps
}: EventContentSlotProps) {
  const { renderEventContent } = useCalendarRenderSlots();
  if (!renderEventContent) return fallback;
  return <div className={className}>{renderEventContent(contentProps)}</div>;
}

"use client";

import * as React from "react";

import type { ViewType } from "./week-view-types";

/**
 * Context to provide the collision boundary element, header inset,
 * and current view type for event detail popovers.
 * - boundary: the outer calendar container (so popovers can position freely)
 * - headerHeight: the height of the weekday header + all-day row,
 *   used as top collision padding so popovers never overlap the header.
 * - view: current calendar view ("day" | "week") — in day view, the collision
 *   boundary is skipped so the popover is positioned within the viewport.
 * - boundaryRight: the right-edge x-coordinate (in viewport px) of the
 *   calendar boundary. Used in day view to place a fixed-position popover
 *   anchor at the calendar's right edge so popovers match Notion Calendar.
 */

interface CalendarPopoverBoundaryValue {
  boundary: HTMLElement | null;
  headerHeight: number;
  view: ViewType;
  /** Right edge of the calendar boundary in viewport pixels. */
  boundaryRight: number;
  /**
   * Bottom edge of the header (weekday + all-day row) in viewport pixels.
   * Used as collision padding top in day view so the popover never overlaps
   * the header area when the collision boundary is the viewport.
   */
  headerBottom: number;
}

/**
 * Floating layers that belong to the calendar: the event details, and the
 * dropdown menus and other popups opened from inside the calendar's own
 * elements (a popover in custom event content, say). Each sits in a portal
 * outside the calendar, yet React still bubbles its events through the
 * views, so presses inside them must not count as clicks on the calendar.
 * The details panel stops its own clicks itself, and those of the popups it
 * renders; these helpers cover the rest, and the details' focus checks.
 * Matches the stock shadcn/ui markup of both the Radix and the Base UI styles
 * (`data-slot` on the menus, the Radix wrapper for anything else it portals).
 */
const CALENDAR_POPOVER_SELECTOR = [
  "[data-calendar-popover]",
  '[data-slot="dropdown-menu-content"]',
  '[data-slot="dropdown-menu-sub-content"]',
  "[data-radix-popper-content-wrapper]",
].join(", ");

/**
 * Whether an element is inside the event details or a menu opened from them.
 * For an event, use {@link isEventInsideCalendarPopover}: a menu may have
 * removed the pressed item from the document before the handler runs.
 */
export function isInsideCalendarPopover(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;
  return target.closest(CALENDAR_POPOVER_SELECTOR) !== null;
}

/**
 * Whether an event fired inside the event details or a menu opened from
 * them. Reads the path the event took when it fired, not the target's
 * current ancestors: Radix closes a menu synchronously when an item is
 * picked, so by the time the calendar's own handlers run the item is no
 * longer in the document, and `closest()` on it finds nothing.
 */
export function isEventInsideCalendarPopover(
  event: Event | React.SyntheticEvent,
): boolean {
  const nativeEvent = "nativeEvent" in event ? event.nativeEvent : event;
  const path = nativeEvent.composedPath();
  if (path.length === 0) return isInsideCalendarPopover(nativeEvent.target);
  return path.some(
    (node) =>
      node instanceof Element && node.matches(CALENDAR_POPOVER_SELECTOR),
  );
}

const CalendarPopoverBoundaryContext =
  React.createContext<CalendarPopoverBoundaryValue>({
    boundary: null,
    headerHeight: 0,
    view: "week",
    boundaryRight: 0,
    headerBottom: 0,
  });

export function CalendarPopoverBoundaryProvider({
  boundaryRef,
  headerRef,
  view = "week",
  children,
}: {
  boundaryRef: React.RefObject<HTMLElement | null>;
  headerRef: React.RefObject<HTMLElement | null>;
  view?: ViewType;
  children: React.ReactNode;
}) {
  const [boundary, setBoundary] = React.useState<HTMLElement | null>(null);
  const [headerHeight, setHeaderHeight] = React.useState(0);
  const [boundaryRight, setBoundaryRight] = React.useState(0);
  const [headerBottom, setHeaderBottom] = React.useState(0);

  React.useEffect(() => {
    setBoundary(boundaryRef.current);
  }, [boundaryRef]);

  // Observe header height changes (all-day row can expand/collapse).
  // Also track the viewport-relative bottom edge of the header for day-view
  // collision padding — the popover must not overlap the header area.
  React.useEffect(() => {
    const el = headerRef.current;
    if (!el) return;

    const update = () => {
      setHeaderHeight(el.offsetHeight);
      setHeaderBottom(el.getBoundingClientRect().bottom);
    };
    update();

    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, [headerRef]);

  // Track the right edge of the calendar boundary for day-view anchoring.
  // A ResizeObserver catches layout changes; we don't need scroll since the
  // boundary element itself doesn't scroll within the viewport.
  React.useEffect(() => {
    const el = boundaryRef.current;
    if (!el) return;

    const update = () => {
      setBoundaryRight(el.getBoundingClientRect().right);
    };
    update();

    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, [boundaryRef]);

  const value = React.useMemo(
    () => ({ boundary, headerHeight, view, boundaryRight, headerBottom }),
    [boundary, headerHeight, view, boundaryRight, headerBottom],
  );

  return (
    <CalendarPopoverBoundaryContext.Provider value={value}>
      {children}
    </CalendarPopoverBoundaryContext.Provider>
  );
}

export function useCalendarPopoverBoundary() {
  return React.useContext(CalendarPopoverBoundaryContext);
}

"use client";

import * as React from "react";

/**
 * Context that carries a one-shot request to focus an event's title input.
 * Set by CalendarProvider right after click-to-create so the user can type a
 * name immediately; the detail panel host that is actually visible (sidebar
 * or popover) consumes it and clears it.
 */
interface EventTitleFocusValue {
  /** ID of the event whose title input should be focused, or null */
  pendingEventId: string | null;
  /** Clears the request once the title input has been focused */
  clearPending: () => void;
}

const EventTitleFocusContext = React.createContext<EventTitleFocusValue>({
  pendingEventId: null,
  clearPending: () => {},
});

export function EventTitleFocusProvider({
  pendingEventId,
  clearPending,
  children,
}: EventTitleFocusValue & { children: React.ReactNode }) {
  const value = React.useMemo(
    () => ({ pendingEventId, clearPending }),
    [pendingEventId, clearPending],
  );

  return (
    <EventTitleFocusContext.Provider value={value}>
      {children}
    </EventTitleFocusContext.Provider>
  );
}

export function useEventTitleFocus() {
  return React.useContext(EventTitleFocusContext);
}

import { cn } from "@/lib/utils";

/** Props for CalendarLoadingBar */
interface CalendarLoadingBarProps {
  /** Classes for the bar's track, e.g. to inset it past the time axis */
  className?: string;
}

/**
 * Thin indeterminate progress bar along the bottom edge of a view's header,
 * drawn while the provider's `loading` prop is set. Place it inside a
 * `relative` header. It takes no pointer events, so everything under it
 * stays usable.
 */
export function CalendarLoadingBar({ className }: CalendarLoadingBarProps) {
  return (
    <div
      role="progressbar"
      aria-label="Loading events"
      data-slot="calendar-loading-bar"
      className={cn(
        "pointer-events-none absolute inset-x-0 bottom-0 h-0.5 overflow-hidden",
        className,
      )}
    >
      <div className="calendar-loading-bar h-full rounded-full bg-muted-foreground/70" />
    </div>
  );
}

import * as React from "react";

import { useCalendar } from "@/components/calendar-provider";
import type { CalendarContextValue } from "@/components/calendar-types";

interface UseCalendarShortcutsOptions {
  /** Whether the shortcuts are active. Defaults to true */
  enabled?: boolean;
}

/** Calendar actions the shortcuts trigger */
type ShortcutActions = Pick<
  CalendarContextValue,
  | "goToToday"
  | "goToPrev"
  | "goToNext"
  | "switchView"
  | "setNumberOfDays"
  | "clearSelection"
  | "toggleWeekends"
  | "toggleDeclinedEvents"
>;

/** Keys 2-9: show that many days */
const NUMBER_OF_DAYS_KEY = /^[2-9]$/;

/** Whether a key press is typed into a text field (single-key shortcuts skip those) */
export function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return target.tagName === "INPUT" || target.tagName === "TEXTAREA";
}

/**
 * Handles one key press. Returns early on the first match, in the same
 * order the demo has always checked them.
 */
function handleShortcut(e: KeyboardEvent, actions: ShortcutActions): void {
  // Escape deselects, even from inside a text field
  if (e.key === "Escape") {
    actions.clearSelection();
    return;
  }

  const isCommand = e.metaKey || e.ctrlKey;
  const key = e.key.toLowerCase();

  // Shift+Cmd+E / Shift+Cmd+D (Ctrl on Windows and Linux) toggle the view
  // settings, even from inside a text field
  if (isCommand && e.shiftKey && key === "e") {
    e.preventDefault();
    actions.toggleWeekends();
    return;
  }

  if (isCommand && e.shiftKey && key === "d") {
    e.preventDefault();
    actions.toggleDeclinedEvents();
    return;
  }

  // Single keys only: Cmd+K, Ctrl+D and the like belong to the app and browser
  if (isCommand || isTypingTarget(e.target)) return;

  if (e.key === "t" || e.key === "T") {
    e.preventDefault();
    actions.goToToday();
    return;
  }

  if (e.key === "1" || e.key === "d" || e.key === "D") {
    e.preventDefault();
    actions.switchView("day");
    return;
  }

  if (e.key === "0" || e.key === "w" || e.key === "W") {
    e.preventDefault();
    actions.switchView("week");
    return;
  }

  if (NUMBER_OF_DAYS_KEY.test(e.key)) {
    e.preventDefault();
    actions.setNumberOfDays(Number(e.key));
    return;
  }

  if (e.key === "j" || e.key === "J" || e.key === "ArrowLeft") {
    e.preventDefault();
    actions.goToPrev();
    return;
  }

  if (e.key === "k" || e.key === "K" || e.key === "ArrowRight") {
    e.preventDefault();
    actions.goToNext();
    return;
  }

  // Lowercase only: Shift+M is left free for app shortcuts
  if (e.key === "m") {
    e.preventDefault();
    actions.switchView("month");
    return;
  }

  // Cmd+A / Ctrl+A never get here, so they still select all
  if (e.key === "a" || e.key === "A") {
    e.preventDefault();
    actions.switchView("agenda");
  }
}

/**
 * Opt-in single-key calendar shortcuts, listening on `window`:
 *
 * - T: today
 * - J / ArrowLeft, K / ArrowRight: previous / next period
 * - D or 1: day view, W or 0: week view, M: month view, A: agenda
 * - 2-9: number of days
 * - Escape: clear the selection
 * - Shift+Cmd+E / Shift+Cmd+D (Ctrl on Windows and Linux): show or hide
 *   weekends / declined events
 *
 * Presses with Cmd or Ctrl are left alone, apart from those two.
 *
 * Key presses in inputs and textareas are ignored (except Escape). The
 * listener is added once on mount, so its position among other `window`
 * keydown listeners stays fixed: an app shortcut that shares a key (e.g.
 * Cmd+K) should be handled by a listener added before this hook's, and call
 * `event.stopImmediatePropagation()`.
 */
export function useCalendarShortcuts({
  enabled = true,
}: UseCalendarShortcutsOptions = {}) {
  const {
    goToToday,
    goToPrev,
    goToNext,
    switchView,
    setNumberOfDays,
    clearSelection,
    toggleWeekends,
    toggleDeclinedEvents,
  } = useCalendar();

  /** Latest actions, read by the window listener */
  const actionsRef = React.useRef<ShortcutActions>({
    goToToday,
    goToPrev,
    goToNext,
    switchView,
    setNumberOfDays,
    clearSelection,
    toggleWeekends,
    toggleDeclinedEvents,
  });

  React.useEffect(() => {
    actionsRef.current = {
      goToToday,
      goToPrev,
      goToNext,
      switchView,
      setNumberOfDays,
      clearSelection,
      toggleWeekends,
      toggleDeclinedEvents,
    };
  }, [
    goToToday,
    goToPrev,
    goToNext,
    switchView,
    setNumberOfDays,
    clearSelection,
    toggleWeekends,
    toggleDeclinedEvents,
  ]);

  React.useEffect(() => {
    if (!enabled) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      handleShortcut(e, actionsRef.current);
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [enabled]);
}

import * as React from "react";

interface UseControllableStateOptions<T> {
  /** Controlled value. `undefined` lets the hook own the value */
  prop: T | undefined;
  /** Initial value (or lazy initializer) when not controlled */
  defaultProp: T | (() => T);
  /** Called with every new value, controlled or not */
  onChange?: (value: T) => void;
}

type UseControllableStateReturn<T> = [
  T,
  (action: React.SetStateAction<T>) => void,
];

/** Whether a state action is an updater function rather than a value */
function isUpdater<T>(
  action: React.SetStateAction<T>,
): action is (prev: T) => T {
  return typeof action === "function";
}

/**
 * State that can be controlled by a parent (`prop` + `onChange`) or owned by
 * the component (`defaultProp`), shadcn/Radix style. The setter accepts a
 * value or an updater, like `useState`, and skips no-op updates.
 */
export function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateOptions<T>): UseControllableStateReturn<T> {
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultProp);
  const isControlled = prop !== undefined;
  const value = prop !== undefined ? prop : uncontrolledValue;

  /** Latest value, read by updaters called outside render */
  const valueRef = React.useRef(value);
  const onChangeRef = React.useRef(onChange);

  React.useEffect(() => {
    valueRef.current = value;
  }, [value]);

  React.useEffect(() => {
    onChangeRef.current = onChange;
  }, [onChange]);

  const setValue = React.useCallback(
    (action: React.SetStateAction<T>) => {
      const next = isUpdater(action) ? action(valueRef.current) : action;
      if (Object.is(next, valueRef.current)) return;
      if (!isControlled) {
        // Owned value: later updaters in the same tick build on this one
        valueRef.current = next;
        setUncontrolledValue(next);
      }
      onChangeRef.current?.(next);
    },
    [isControlled],
  );

  return [value, setValue];
}

"use client";

import { useCallback } from "react";

import { useCalendar, useCalendarConfig } from "@/components/calendar-provider";
import { getKeyboardEventChange } from "@/lib/event-utils";

interface UseEventKeyboardOptions {
  /** Element holding the view's events; focus is put back on an event inside it */
  containerRef: React.RefObject<HTMLElement | null>;
  /** Vertically scrolling element, kept scrolled to the focused event */
  scrollContainerRef?: React.RefObject<HTMLElement | null>;
  /** Whether a day is on screen; a keyboard move off screen calls `revealDay` */
  isDayVisible: (date: Date) => boolean;
  /** Navigates the view so the day is on screen */
  revealDay: (date: Date) => void;
}

/** Arrow keys that, with Alt, move (or with Alt+Shift, resize) the focused event */
const EVENT_MOVE_KEYS = new Set([
  "ArrowUp",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
]);

/**
 * Keys that select, open or close the focused event. Opening or closing its
 * popover can re-create the event's element, so focus is put back on it.
 */
const FOCUS_KEEPING_KEYS = new Set(["Enter", " ", "Escape"]);

/**
 * Focuses the event's element inside `container` and returns it, or `null`
 * when none takes focus. Inert (off-screen buffer) copies refuse focus, so
 * each match is tried in turn.
 */
export function focusEventElement(
  container: HTMLElement | null,
  eventId: string,
): HTMLElement | null {
  if (!container) return null;
  const candidates = container.querySelectorAll<HTMLElement>(
    `[data-event-id="${CSS.escape(eventId)}"]`,
  );
  for (const candidate of candidates) {
    candidate.focus({ preventScroll: true });
    if (document.activeElement === candidate) return candidate;
  }
  return null;
}

/** Scrolls `scroller` vertically just enough to show `element` */
function keepInView(element: HTMLElement, scroller: HTMLElement | null) {
  if (!scroller) return;
  const elementRect = element.getBoundingClientRect();
  const scrollerRect = scroller.getBoundingClientRect();
  if (elementRect.top < scrollerRect.top) {
    scroller.scrollTop -= scrollerRect.top - elementRect.top;
    return;
  }
  if (elementRect.bottom > scrollerRect.bottom) {
    scroller.scrollTop += elementRect.bottom - scrollerRect.bottom;
  }
}

/**
 * Keyboard editing for a view's events, as a keydown handler for the view's
 * root. On a focused event (an element with `data-event-id`):
 *
 * - Alt+ArrowLeft/Right moves it a day; Alt+ArrowUp/Down moves it one
 *   `snapMinutes` step (a week in month view); Alt+Shift+ArrowUp/Down
 *   resizes its end (see `getKeyboardEventChange`)
 * - Enter, Space and Escape keep focus on it while its popover opens or closes
 *
 * Handled keys don't reach the calendar shortcuts (where arrows change the
 * period) or the browser (where Alt+Arrow navigates history).
 */
export function useEventKeyboard({
  containerRef,
  scrollContainerRef,
  isDayVisible,
  revealDay,
}: UseEventKeyboardOptions): (e: React.KeyboardEvent<HTMLElement>) => void {
  const { events, view, updateEvent } = useCalendar();
  const config = useCalendarConfig();

  /**
   * After React re-renders, focuses the event's element again if focus was
   * lost (its element was re-created), and keeps it scrolled into view.
   * Focus that moved somewhere else on purpose is left alone. (Escape with
   * the popover open is handled by the popover: it closes first.)
   */
  const restoreFocus = useCallback(
    (eventId: string) => {
      requestAnimationFrame(() => {
        const container = containerRef.current;
        if (!container) return;
        const scroller = scrollContainerRef?.current ?? null;

        const active = document.activeElement;
        if (
          active instanceof HTMLElement &&
          active.dataset.eventId === eventId
        ) {
          keepInView(active, scroller);
          return;
        }
        if (active && active !== document.body) return;

        const focused = focusEventElement(container, eventId);
        if (focused) keepInView(focused, scroller);
      });
    },
    [containerRef, scrollContainerRef],
  );

  return useCallback(
    (e: React.KeyboardEvent<HTMLElement>) => {
      if (!(e.target instanceof HTMLElement)) return;
      const eventId =
        e.target.closest<HTMLElement>("[data-event-id]")?.dataset.eventId;
      if (!eventId) return;

      if (FOCUS_KEEPING_KEYS.has(e.key)) {
        restoreFocus(eventId);
        return;
      }
      if (!e.altKey || e.ctrlKey || e.metaKey) return;
      if (!EVENT_MOVE_KEYS.has(e.key)) return;

      e.preventDefault();
      e.stopPropagation();

      const event = events.find((ev) => ev.id === eventId);
      if (!event) return;
      const changed = getKeyboardEventChange(
        event,
        e.key,
        e.shiftKey,
        view,
        config,
      );
      if (!changed) return;

      updateEvent(changed);
      if (!isDayVisible(changed.start)) revealDay(changed.start);
      restoreFocus(eventId);
    },
    [events, view, config, updateEvent, isDayVisible, revealDay, restoreFocus],
  );
}

import * as React from "react";
import { startOfDay } from "date-fns";

/**
 * Milliseconds between clock ticks. Ticks land on multiples of this value
 * (minute boundaries), so the current-time line moves when the minute does.
 */
const NOW_TICK_INTERVAL_MS = 60_000;

/** Components subscribed to the shared clock. */
const listeners = new Set<() => void>();

/** Timestamp handed to subscribers. Refreshed on every tick. */
let nowSnapshot: number | null = null;

/** Pending tick, or `null` while nothing is subscribed. */
let tickTimeout: ReturnType<typeof setTimeout> | null = null;

/** Returns the index of the tick interval a timestamp falls in. */
function getTickIndex(timestamp: number): number {
  return Math.floor(timestamp / NOW_TICK_INTERVAL_MS);
}

/**
 * Returns the shared "now" timestamp.
 *
 * The value stays the same within one tick interval, so repeated reads during
 * a render agree with each other. It is refreshed lazily when a read lands in
 * a later interval, which covers renders that happen while nothing is
 * subscribed (and so no timer is running).
 */
function readNow(): number {
  const current = Date.now();
  if (
    nowSnapshot === null ||
    getTickIndex(current) !== getTickIndex(nowSnapshot)
  ) {
    nowSnapshot = current;
  }
  return nowSnapshot;
}

/** Schedules the next tick on the next interval boundary. */
function scheduleTick(): void {
  const delay = NOW_TICK_INTERVAL_MS - (Date.now() % NOW_TICK_INTERVAL_MS);
  tickTimeout = setTimeout(() => {
    nowSnapshot = Date.now();
    listeners.forEach((listener) => listener());
    scheduleTick();
  }, delay);
}

/** Subscribes to the shared clock. One timer serves every subscriber. */
function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  if (tickTimeout === null) {
    scheduleTick();
  }

  return () => {
    listeners.delete(listener);
    if (listeners.size > 0 || tickTimeout === null) return;
    clearTimeout(tickTimeout);
    tickTimeout = null;
  };
}

function getNowSnapshot(): number {
  return readNow();
}

function getTodaySnapshot(): number {
  return startOfDay(readNow()).getTime();
}

/**
 * Server and hydration snapshot. `null` means "the time is not known yet",
 * so nothing that depends on the clock or the viewer's timezone is rendered
 * and server and client markup match (React error #418).
 */
function getServerSnapshot(): null {
  return null;
}

/** Server and hydration snapshot for `useIsPast`: nothing is past yet. */
function getServerIsPastSnapshot(): boolean {
  return false;
}

/**
 * Returns the current time, updated on every minute boundary.
 *
 * Returns `null` during server rendering and hydration, and the real time
 * right after hydration. Client-only renders get the real time on the first
 * render. Components must render their time-dependent parts only when the
 * value is not `null`.
 */
export function useNow(): Date | null {
  const timestamp = React.useSyncExternalStore<number | null>(
    subscribe,
    getNowSnapshot,
    getServerSnapshot,
  );

  return React.useMemo(
    () => (timestamp === null ? null : new Date(timestamp)),
    [timestamp],
  );
}

/**
 * Returns the start of the viewer's current day, or `null` during server
 * rendering and hydration.
 *
 * Shares the clock with `useNow`, but the component re-renders only when the
 * day changes, not on every tick.
 */
export function useToday(): Date | null {
  const timestamp = React.useSyncExternalStore<number | null>(
    subscribe,
    getTodaySnapshot,
    getServerSnapshot,
  );

  return React.useMemo(
    () => (timestamp === null ? null : new Date(timestamp)),
    [timestamp],
  );
}

/**
 * Returns whether `date` is in the past.
 *
 * Returns `false` during server rendering and hydration. Shares the clock
 * with `useNow`, but the component re-renders only when the answer changes,
 * not on every tick.
 */
export function useIsPast(date: Date): boolean {
  const timestamp = date.getTime();
  const getSnapshot = React.useCallback(
    () => timestamp < readNow(),
    [timestamp],
  );

  return React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    getServerIsPastSnapshot,
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";
import type { PointerGestureStart } from "@/components/week-view-types";

interface UsePointerGestureOptions {
  /**
   * Element the gestures start in. A no-op, non-passive touchmove listener
   * on it keeps the browser from treating its touch moves as uncancelable,
   * so a long press that became a drag can stop the page from scrolling.
   */
  containerRef: React.RefObject<HTMLElement | null>;
}

interface UsePointerGestureReturn {
  /**
   * Starts a press-to-drag gesture from a pointerdown. Mouse and pen start
   * right away; touch starts after a long press, so a finger that moves
   * first scrolls the page instead. Non-primary pointers and buttons are
   * ignored.
   */
  startGesture: (
    e: React.PointerEvent<HTMLElement>,
    onStart: (start: PointerGestureStart) => void,
  ) => void;
}

/** How long (ms) a finger must rest before a touch drag, resize or create starts */
export const LONG_PRESS_DELAY_MS = 350;

/**
 * How far (px) a finger may move during the long press. Moving further
 * cancels it, so the gesture scrolls instead.
 */
export const LONG_PRESS_MOVE_TOLERANCE_PX = 8;

/**
 * How long (ms) after a touch gesture ends its follow-up mousedown, click
 * and long-press context menu are swallowed. Mouse and pen clicks follow
 * pointerup in the same task, so for them the window closes on the next one.
 */
const TOUCH_FOLLOW_UP_WINDOW_MS = 400;

/** A touch waiting for its long press, or a long press that started a gesture */
interface TouchPress {
  pointerId: number;
  startClientX: number;
  startClientY: number;
  /** Latest position, where the gesture starts when the long press completes */
  lastClientX: number;
  lastClientY: number;
  element: HTMLElement;
  /**
   * Node the touch events target. Browsers keep sending them there even
   * after it is removed from the DOM mid-drag, when they no longer bubble.
   */
  touchTarget: EventTarget;
  /** Whether the long press completed and the gesture is running */
  isActive: boolean;
  /** The element's inline touch-action before the gesture, restored after it */
  previousTouchAction: string;
  timer: ReturnType<typeof setTimeout> | null;
}

/** Whether a pointerdown can start a gesture: the primary pointer's main button (left mouse button, pen tip or a finger) */
export function isPrimaryPress(e: React.PointerEvent | PointerEvent): boolean {
  return e.isPrimary && e.button === 0;
}

/** Swallows the next `type` event the browser sends within `windowMs` */
function swallowNext(type: "click" | "mousedown", windowMs: number): void {
  const stop = () => {
    window.removeEventListener(type, swallow, true);
    clearTimeout(timer);
  };
  function swallow(e: Event) {
    e.preventDefault();
    e.stopPropagation();
    stop();
  }
  window.addEventListener(type, swallow, true);
  const timer = setTimeout(stop, windowMs);
}

/**
 * Swallows the click the browser sends right after a drag, resize or touch
 * gesture ends. When the pressed element was swapped out mid-drag (for a
 * ghost or a floating copy), that click lands on a shared ancestor and would
 * read as a background click that clears the selection.
 */
export function suppressNextClick(pointerType: string): void {
  swallowNext("click", pointerType === "touch" ? TOUCH_FOLLOW_UP_WINDOW_MS : 0);
}

/** Keeps the long-press context menu from opening over a touch gesture */
function blockContextMenu(e: Event) {
  e.preventDefault();
  e.stopPropagation();
}

/** Registered only to make touch moves in the container cancelable */
function noop() {}

/**
 * Turns pointerdowns into press-to-drag gestures for the drag and resize
 * hooks: immediately for mouse and pen, after a long press for touch.
 * While a touch gesture runs, the pressed element gets `touch-action: none`,
 * page scrolling and the context menu are blocked, and the click that
 * follows it is swallowed.
 */
export function usePointerGesture({
  containerRef,
}: UsePointerGestureOptions): UsePointerGestureReturn {
  const pressRef = useRef<TouchPress | null>(null);
  const handlePressMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePressEndRef = useRef<((e: PointerEvent) => void) | null>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    container.addEventListener("touchmove", noop, { passive: false });
    return () => container.removeEventListener("touchmove", noop);
  }, [containerRef]);

  /** Stops the page from scrolling once the long press has completed */
  const blockTouchMove = useCallback((e: Event) => {
    if (!pressRef.current?.isActive || !e.cancelable) return;
    e.preventDefault();
  }, []);

  /** Ends the current touch press, whether it was pending or active */
  const finishPress = useCallback(() => {
    const press = pressRef.current;
    if (!press) return;
    pressRef.current = null;

    if (press.timer !== null) clearTimeout(press.timer);
    if (handlePressMoveRef.current) {
      window.removeEventListener("pointermove", handlePressMoveRef.current);
    }
    if (handlePressEndRef.current) {
      window.removeEventListener("pointerup", handlePressEndRef.current);
      window.removeEventListener("pointercancel", handlePressEndRef.current);
    }
    press.touchTarget.removeEventListener("touchmove", blockTouchMove);

    if (!press.isActive) return;
    press.element.style.touchAction = press.previousTouchAction;
    // The browser may still send the touch's compatibility mousedown and
    // click. The mousedown would move focus (e.g. off a just-created
    // event's title) and the click would read as a background click.
    swallowNext("mousedown", TOUCH_FOLLOW_UP_WINDOW_MS);
    suppressNextClick("touch");
    setTimeout(() => {
      window.removeEventListener("contextmenu", blockContextMenu, true);
    }, TOUCH_FOLLOW_UP_WINDOW_MS);
  }, [blockTouchMove]);

  useEffect(() => {
    handlePressMoveRef.current = (e: PointerEvent) => {
      const press = pressRef.current;
      if (!press || e.pointerId !== press.pointerId) return;
      press.lastClientX = e.clientX;
      press.lastClientY = e.clientY;
      if (press.isActive) return;

      const distance = Math.hypot(
        e.clientX - press.startClientX,
        e.clientY - press.startClientY,
      );
      if (distance <= LONG_PRESS_MOVE_TOLERANCE_PX) return;
      // Moved before the long press completed: let the browser scroll
      finishPress();
    };

    handlePressEndRef.current = (e: PointerEvent) => {
      const press = pressRef.current;
      if (!press || e.pointerId !== press.pointerId) return;
      finishPress();
    };
  }, [finishPress]);

  // Cancel a pending or running touch press on unmount
  useEffect(() => {
    return finishPress;
  }, [finishPress]);

  const startGesture = useCallback(
    (
      e: React.PointerEvent<HTMLElement>,
      onStart: (start: PointerGestureStart) => void,
    ) => {
      if (!isPrimaryPress(e)) return;

      const element = e.currentTarget;
      if (e.pointerType !== "touch") {
        onStart({
          clientX: e.clientX,
          clientY: e.clientY,
          pointerId: e.pointerId,
          pointerType: e.pointerType,
          element,
        });
        return;
      }

      finishPress();
      const press: TouchPress = {
        pointerId: e.pointerId,
        startClientX: e.clientX,
        startClientY: e.clientY,
        lastClientX: e.clientX,
        lastClientY: e.clientY,
        element,
        touchTarget: e.target,
        isActive: false,
        previousTouchAction: "",
        timer: null,
      };
      pressRef.current = press;

      press.touchTarget.addEventListener("touchmove", blockTouchMove, {
        passive: false,
      });
      if (handlePressMoveRef.current) {
        window.addEventListener("pointermove", handlePressMoveRef.current);
      }
      if (handlePressEndRef.current) {
        window.addEventListener("pointerup", handlePressEndRef.current);
        window.addEventListener("pointercancel", handlePressEndRef.current);
      }

      press.timer = setTimeout(() => {
        press.timer = null;
        press.isActive = true;
        press.previousTouchAction = element.style.touchAction;
        element.style.touchAction = "none";
        window.addEventListener("contextmenu", blockContextMenu, true);
        onStart({
          clientX: press.lastClientX,
          clientY: press.lastClientY,
          pointerId: press.pointerId,
          pointerType: "touch",
          element,
        });
      }, LONG_PRESS_DELAY_MS);
    },
    [finishPress, blockTouchMove],
  );

  return { startGesture };
}

import * as React from "react";

import { getTimeZoneDisplayName, getTimeZoneLabel } from "@/lib/timezone-label";

/**
 * Label rendered on the server and during hydration. It must not depend on
 * the runtime's timezone, or server and client markup would differ (#418).
 */
const SERVER_TIMEZONE_LABEL = "";

/** No-op subscription: the label is re-read on every client render. */
function subscribe(): () => void {
  return () => {};
}

function getClientSnapshot(): string {
  return getTimeZoneLabel(new Date());
}

function getClientDisplayNameSnapshot(): string {
  return getTimeZoneDisplayName(new Date());
}

function getServerSnapshot(): string {
  return SERVER_TIMEZONE_LABEL;
}

/**
 * Returns the viewer's short timezone label ("EDT", "GMT-3", "GMT+5:30").
 *
 * Server rendering and the client's hydration render both return
 * `SERVER_TIMEZONE_LABEL`, so the markup matches. React then re-renders
 * with the client snapshot right after hydration. Client-only renders
 * (no SSR) get the real label on the first render.
 */
export function useTimeZoneLabel(): string {
  return React.useSyncExternalStore(
    subscribe,
    getClientSnapshot,
    getServerSnapshot,
  );
}

/**
 * Returns the viewer's timezone label with its city ("GMT-3 Sao Paulo",
 * "EDT New York"). Like `useTimeZoneLabel`, it is empty on the server and
 * during hydration.
 */
export function useTimeZoneDisplayName(): string {
  return React.useSyncExternalStore(
    subscribe,
    getClientDisplayNameSnapshot,
    getServerSnapshot,
  );
}

